def is_geometric_progression(arr):
    n = len(arr)
    if n <= 2:
        return True

    # Special case: all zeros
    if all(x == 0 for x in arr):
        return True

    # Determine possible common ratio
    # If arr[0] == 0 and arr[1] != 0, impossible
    if arr[0] == 0 and arr[1] != 0:
        return False

    # If first element is non-zero, compute ratio
    if arr[0] != 0:
        # For integer arrays, check using multiplication to avoid floating point
        # a[i] = a[0] * r^(i-1) for i >= 1

        # Find the ratio by comparing the first two non-zero or zero elements
        first_nonzero_idx = 0
        while first_nonzero_idx < n and arr[first_nonzero_idx] == 0:
            first_nonzero_idx += 1

        if first_nonzero_idx >= n - 1:
            return all(x == 0 for x in arr)

        if first_nonzero_idx < n and arr[first_nonzero_idx + 1] != 0:
            # Compute ratio and check
            # Use cross multiplication to avoid floating point issues
            ratio_numer = arr[first_nonzero_idx + 1]
            ratio_denom = arr[first_nonzero_idx]

            for i in range(2, n):
                expected = arr[0] if i == 1 else arr[i - 1] * ratio_numer // ratio_denom
                # Check if arr[i] matches the pattern
                # For each step: arr[i] should equal arr[0] * (ratio_numer/ratio_denom)^(i)
                # Actually, simpler: arr[i] / arr[i-1] should equal ratio numerator/denominator
                if arr[i - 1] != 0:
                    if arr[i] * ratio_denom != arr[i - 1] * ratio_numer:
                        return False
                else:
                    # Previous element is 0, so arr[i] must also be 0
                    if arr[i] != 0:
                        return False
            return True
        else:
            return all(x == 0 for x in arr)
    else:
        # arr[0] == 0, arr[1] must also be 0 for GP
        return all(x == 0 for x in arr)


def can_be_geometric_progression_by_deletion(arr):
    n = len(arr)
    if n <= 2:
        return True

    # Try removing each element
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_geometric_progression(new_arr):
            return True

    return False

def itoa(x):
    chars = []
    if x == 0:
        return "0"
    while x > 0:
        chars.append(str(x % 10))
        x //= 10
    return ''.join(chars[::-1])

def solution(data: str) -> str:
    t = int(data.split('\n')[0])
    lines = data.split('\n')
    results = []

    for i in range(1, t + 1):
        n, k = map(int, lines[i].split())

        if k > n:
            results.append(str(n))
        else:
            # Use formula
            # m is cycle number where n appears
            # find m such that next_v <= n <= next_v + k - 1 or n = sum
            # next_v = m * (k + 1) + 1

            # Skip cycles similar amounts
            m = n // (k + 1)
            next_v = m * (k + 1) + 1

            # Determine if n falls in the next cycle
            if next_v <= n <= next_v + k - 1:
                pos = next_v + n - next_v + 1
            elif n == k * next_v + k * (k - 1) // 2:
                pos = m * (k + 1) + k + 1
            else:
                # n might be the sum of a previous cycle
                results.append(str(pos))

    return '\n'.join(results)

