def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if not lines or not lines[idx]:
        return ""

    n = int(lines[idx].strip())
    idx += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        if idx >= len(lines):
            break
        u, v = map(int, lines[idx].strip().split())
        adj[u].append(v)
        adj[v].append(u)
        idx += 1

    if idx < len(lines):
        k = int(lines[idx].strip())
        idx += 1
        if idx < len(lines):
            chips = list(map(int, lines[idx].strip().split()))
        else:
            chips = []
    else:
        k = 0
        chips = []

    # Multi-source BFS from all chip positions
    dist = [-1] * (n + 1)
    queue = collections.deque()

    for chip in chips:
        if 1 <= chip <= n:
            dist[chip] = 0
            queue.append(chip)

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    result = []
    for i in range(1, n + 1):
        # If a Bob's chip is at vertex i, answer is 0
        if dist[i] == 0:
            result.append('0')
        else:
            # The game lasts dist[i] turns (shortest distance to any chip)
            result.append(str(dist[i]))

    return ' '.join(result)


