def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Implication graph: 2*m nodes
    # Node 2*i represents variable x_{i+1} as TRUE
    # Node 2*i+1 represents variable x_{i+1} as FALSE
    adj = [[] for _ in range(2 * m)]

    for i in range(n):
        line = lines[i + 1] if i < len(lines) - 1 else ''
        parts = list(map(int, line.split()))
        ki = parts[0]
        literals = parts[1:]

        # Convert literals to node indices
        lit_nodes = []
        for lit in literals:
            var_idx = abs(lit) - 1  # Convert 1-indexed to 0-indexed
            if lit < 0:
                lit_nodes.append(2 * var_idx + 1)  # FALSE
            else:
                lit_nodes.append(2 * var_idx)      # TRUE

        # For each pair of literals, create implications
        # (A ∨ B) means: ¬A → B AND ¬B → A
        for i in range(ki):
            node_i = lit_nodes[i]
            neg_node_i = node_i + 1 if node_i % 2 == 0 else node_i - 1

            for j in range(i + 1, ki):
                node_j = lit_nodes[j]
                if node_j % 2 == 0:
                    neg_node_j = node_j + 1
                else:
                    neg_node_j = node_j - 1

                adj[neg_node_i].append(node_j)
                adj[neg_node_j].append(node_i)

    # Tarjan's algorithm for SCC
    visited = [False] * (2 * m)
    on_stack = [False] * (2 * m)
    stack = []
    scc_id = [0] * (2 * m)
    disc = [0] * (2 * m)
    low = [0] * (2 * m)
    visited_time = 0
    timer = [0]

    def tarjan(u):
        nonlocal visited_time
        visited[u] = True
        stack.append(u)
        on_stack[u] = True
        disc[u] = low[u] = visited_time
        visited_time += 1

        for v in adj[u]:
            if v < 2 * m and not visited[v]:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif v < 2 * m and on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            while stack:
                w = stack.pop()
                on_stack[w] = False
                scc_id[w] = timer[0]
            timer[0] += 1

    for i in range(2 * m):
        if not visited[i]:
            tarjan(i)

    # Check satisfiability
    for i in range(m):
        if scc_id[2 * i] == scc_id[2 * i + 1]:
            return "NO\n" + "0" * m

    # Build assignment based on topological order
    result = []
    for i in range(m):
        if scc_id[2 * i] < scc_id[2 * i + 1]:
            result.append("1")
        else:
            result.append("0")

    return "YES\n" + "".join(result)

