def solution(text):
    lines = text.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if n == 1:
        return "-1\n"

    total = sum(a)
    if total < 2:
        return "-1\n"

    # Find all divisors of total
    divisors = []
    for i in range(2, int(total**0.5) + 1):
        if total % i == 0:
            divisors.append(i)
            if i != total // i:
                divisors.append(total // i)
    divisors.append(total)

    def calc_cost(arr, k):
        cost = 0
        rem = 0
        # We need n elements but process first n-1 for cost calculation
        for i in range(len(arr)):
            rem = (rem + arr[i]) % k
            cost += rem
        return cost

    min_cost = float('inf')
    for k in divisors:
        min_cost = min(min_cost, calc_cost(a, k))

    return f"{min_cost}\n"

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse operations
    ops = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t_step = int(parts[0])
        x_p = int(parts[1])
        y = int(parts[2])
        x_val = x_p / 100000.0
        ops.append((t_step, x_p, y, x_val))

    # min_time[j] = earliest time step to get exactly j bananas (-1 if impossible)
    min_time = [-1] * (m + 1)
    min_time[0] = 0  # 0 bananas at time step 0

    # Track which states are reachable at each time step
    current = {0}

    for step in range(1, n + 1):
        t_step, x_p, y, x_val = ops[step - 1]

        next_step = set()

        for k in current:
            # Option a_i = 0: don't apply operation
            next_step.add(k)

            # Option a_i > 0: apply operation up to y times
            if t_step == 1:  # Type 1: k := ceil(k + x)
                temp = k
                for apply_count in range(1, y + 1):
                    temp = math.ceil(temp + x_val)
                    if temp <= m:
                        next_step.add(int(temp))
                    else:
                        break
            else:  # Type 2: k := ceil(k * x)
                temp = k
                for apply_count in range(1, y + 1):
                    temp = math.ceil(temp * x_val)
                    if temp <= m:
                        next_step.add(int(temp))
                    else:
                        break

        # Update min_time for new states (first time reached)
        for state in next_step:
            if min_time[state] == -1:
                min_time[state] = step

        current = next_step

    # Build result string (for j from 1 to m)
    result = []
    for j in range(1, m + 1):
        result.append(str(min_time[j]))

    return ' '.join(result)

