import sys

def bfs(adj, start, end):
    """Check if end is reachable from start in the given graph."""
    visited = [False] * (len(adj) + 1)
    queue = [start]
    visited[start] = True

    while queue:
        u = queue.pop(0)
        if u == end:
            return True
        for v, _ in adj[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)
    return False

def solution(input_data):
    lines = input_data.strip().split('\n')
    if len(lines) < 2:
        return "-1"

    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []  # list of (u, v, w, index)
    adj = defaultdict(list)

    for i in range(m):
        parts = lines[2 + i].split()
        if len(parts) < 3:
            continue
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((u, v, w, i + 1))
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))

    # Check if already disconnected (cost = 0, no edges to remove)
    if not bfs(adj, s, t):
        return "0\n0\n"

    best_single_cost = float('inf')
    best_single_edge = None

    # Check single edge removal
    for u1, v1, w1, e1 in edges:
        # Temporarily remove edge e1
        new_adj = defaultdict(list)
        for node, edge_list in adj.items():
            for neighbor, edge_id in edge_list:
                if edge_id != e1:
                    new_adj[node].append((neighbor, edge_id))

        if not bfs(new_adj, s, t):
            if w1 < best_single_cost:
                best_single_cost = w1
                best_single_edge = e1
            ans_single = True
            ans_single_edge = [e1]
            ans_single_cost = w1
        else:
            annial_adj = adj  # Restore
            annial_adj[u1].append((v1, e1))
            annial_adj[v1].append((u1, e1))

    # Check two edge removal
    best_2_cost = float('inf')
    best_2_edges = None
    ans_two = False
    ans_two_edges = None
    ans_two_cost = float('inf')

    for i in range(m):
        u1, v1, w1, e1 = edges[i]
        # Temporarily remove edge e1
        new_adj = defaultdict(list)
        for node, edge_list in adj.items():
            for neighbor, edge_id in edge_list:
                if edge_id != e1:
                    new_adj[node].append((neighbor, edge_id))

        for j in range(i, m):
            u2, v2, w2, e2 = edges[j]
            # Temporarily remove edges e1 and e2
            tmp_adj = defaultdict(list)
            for node, edge_list in new_adj.items():
                for neighbor, edge_id in edge_list:
                    if edge_id != e1 and edge_id != e2:
                        tmp_adj[node].append((neighbor, edge_id))

            if not bfs(tmp_adj, s, t):
                cost = w1 + w2
                if cost < best_2_cost:
                    best_2_edges = (e1, e2)
                    best_2_cost = cost
                    ans_two = True
                    ans_two_edges = [e1, e2]
                    ans_two_cost = cost

            # Restore e2
            new_adj[u2].append((v2, e2))
            new_adj[v2].append((u2, e2))

        # Restore e1
        adj[u1].append((v1, e1))
        adj[v1].append((u1, e1))

    # Determine the best solution
    if ans_single is not None:
        result_str = f"{ans_single_cost}\n1\n" + " ".join(map(str, ans_single_edge))
    elif ans_two is True:
        result_str = f"{ans_two_cost}\n2\n" + " ".join(map(str, ans_two_edges))
    else:
        result_str = "-1"

    return result_str

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1\n'

    n, m = map(int, lines[0].split())
    if n < 1 or m < 1 or n * m < 1:
        return '-1\n'

    grid = []
    for i in range(1, min(n, len(lines)) + 1):
        if i <= len(lines):
            row = list(map(int, lines[i].split()))
            if len(row) != m:
                return '-1\n'
            grid.append(row)

    if len(grid) != n:
        return '-1\n'

    # Check all values 1 to n*m are present
    expected = set(range(1, n * m + 1))
    actual = set()
    for row in grid:
        actual.update(row)

    if actual != expected:
        return '-1\n'

    # Extract row and column maximums
    row_maxes = set()
    for row in grid:
        row_maxes.add(max(row))

    col_maxes = set()
    for c in range(m):
        col_maxes.add(max(grid[r][c] for r in range(n)))

    # Bitonic check: increases then decreases (strictly)
    def is_bitonic(arr):
        if len(arr) <= 1:
            return True
        # Find peak
        peak_idx = 0
        for i in range(1, len(arr)):
            if arr[i] < arr[i-1]:
                break
            peak_idx = i

        # Check decreasing after peak
        for i in range(peak_idx + 1, len(arr)):
            if arr[i] >= arr[i-1]:
                return False
        return True

    # Construct the result matrix
    # Strategy: place numbers greedily to maintain bitonic properties
    result = [[0] * m for _ in range(n)]
    used = [False] * (n * m + 1)

    # Try to construct a valid bitonic matrix
    # Process in some order to maintain properties
    for val in range(1, n * m + 1):
        placed = False

        # Find a position where val can be placed
        for r in range(n):
            for c in range(m):
                if result[r][c] == 0:
                    # Check if placing val here maintains potential bitonic property
                    row_ok = True
                    col_ok = True

                    # Check row neighbors
                    for k in range(m):
                        if result[r][k] > 0:
                            left_inc = k < c and result[r][k] < val
                            right_dec = k > c and result[r][k] < val
                            left_dec = k < c and result[r][k] > val
                            right_inc = k > c and result[r][k] > val

                            if left_dec and not left_inc:
                                row_ok = False
                            if right_inc and not right_dec:
                                row_ok = False

                    # Check col neighbors
                    for k in range(n):
                        if result[k][c] > 0:
                            top_inc = k < r and result[k][c] < val
                            bottom_dec = k > r and result[k][c] < val
                            top_dec = k < r and result[k][c] > val
                            bottom_inc = k > r and result[k][c] > val

                            if top_dec and not top_inc:
                                col_ok = False
                            if bottom_inc and not bottom_dec:
                                col_ok = False

                    if row_ok and col_ok:
                        result[r][c] = val
                        used[val] = True
                        placed = True
                        break
            if placed:
                break
        if not placed:
            return '-1\n'

    # Verify all rows are bitonic
    for r in range(n):
        if not is_bitonic(result[r]):
            return '-1\n'

    # Verify all columns are bitonic
    for c in range(m):
        col = [result[r][c] for r in range(n)]
        if not is_bitonic(col):
            return '-1\n'

    # Verify spectral properties
    new_row_maxes = set()
    for row in result:
        new_row_maxes.add(max(row))

    new_col_maxes = set()
    for c in range(m):
        new_col_maxes.add(max(result[r][c] for r in range(n)))

    if new_row_maxes != row_maxes or new_col_maxes != col_maxes:
        # Try alternative construction
        return '-1\n'

    return '\n'.join(' '.join(map(str, row)) for row in result) + '\n'

