def solution(input_str):
    """
    Solves the problem of finding the maximum number of chessmen that can be placed
    on an n x m chessboard where each placement requires two cells at Manhattan distance exactly 3.

    The key observations:
    1. Manhattan distance 3 pairs cells of different colors in the chessboard bipartition (black/white)
    2. For small boards (2x2), no such pairs exist, so answer is 0
    3. For small boards (1xN where N<4), no distance-3 pairs exist, so answer is 0
    4. For larger boards, we can typically achieve a near-perfect matching:
       - If total cells is even: n*m chessmen (all cells can be paired)
       - If total cells is odd: n*m-1 chessmen (one cell must remain unused)
    """
    try:
        parts = input_str.strip().split()
        if not parts:
            return "0"
        n = int(parts[0])
        m = int(parts[1])

        # Handle edge cases where distance-3 pairs cannot be formed
        if n <= 2 and m <= 2:
            return "0"

        if n == 1:
            # 1×m board: need at least 4 cells to have any distance-3 pairs
            if m < 4:
                return "0"
            # For 1×m with m >= 4, maximum matching leaves at most 1 cell unused
            total = n * m
            return str(total - (total % 2))

        if m == 1:
            # Same as above for 1×n
            if n < 4:
                return "0"
            total = n * m
            return str(total - (total % 2))

        # For general case (both dimensions >= 3 and at least one is >= 2):
        # We can achieve near-perfect matching
        total = n * m
        return str(total - (total % 2))

    except (ValueError, IndexError):
        return "0"

