    visited = [False] * n
    components = []
    for i in range(n):
        if not visited[i]:
            comp = []
            queue = deque([i])
            visited[i] = True
            while queue:
                u = queue.popleft()
                comp.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
            components.append(comp)

    # For each component, sum of initial soldiers must equal sum of target soldiers
    for comp in components:
        if sum(a[i] for i in comp) != sum(b[i] for i in comp):
            return "NO"

    # Build flow network
    source = n
    sink = n + 1
    capacity = {}

    def add_edge(u, v, c):
        if (u, v) not in capacity:
            capacity[(u, v)] = 0
        if (v, u) not in capacity:
            capacity[(v, u)] = 0
        capacity[(u, v)] += c

    # Source to each city (availability)
    for i in range(n):
        add_edge(source, i, a[i])
        add_edge(i, sink, b[i])
        # Staying at home
        add_edge(i, i, a[i])
        # Move to neighbors
        for j in adj[i]:
            add_edge(i, j, a[i])

    max_flow = 0
    parent = {}

    def bfs():
        queue = deque([source])
        visited_flow = {source}
        parent = {source: None}
        while queue:
            u = queue.popleft()
            if u == sink:
                return True
            for v in range(n + 1):
                if v not in visited_flow and (u, v) in capacity and capacity[(u, v)] > 0:
                    visited_flow.add(v)
                    parent[v] = u
                    queue.append(v)
        return False

    # Track actual flow per edge for reconstruction
    flow_on_edge = {}

    while bfs():
        # Find bottleneck
        path_flow = float('inf')
        curr = sink
        while curr != source:
            prev = parent[curr]
            path_flow = min(path_flow, capacity[(prev, curr)])
            curr = prev

        # Augment flow
        curr = sink
        while curr != source:
            prev = parent[curr]
            capacity[(prev, curr)] -= path_flow
            capacity[(curr, prev)] += path_flow
            flow_on_edge[(prev, curr)] = flow_on_edge.get((prev, curr), 0) + path_flow
            curr = prev

        max_flow += path_flow

    if max_flow != sum(b):
        return "NO"

    # Reconstruct solution matrix
    # Matrix[i][j] = soldiers moving from city i to city j
    # Note: The flow algorithm routes available soldiers through paths
    # We need to extract movements properly

    adj_matrix = [[0] * n for _ in range(n)]

    # Each city i's soldiers are distributed based on flow
    # For each source node, track how much flow went to each destination
    for i in range(n):
        # Flow from i to j represents soldiers moving from i to j (if j is not source/sink)
        for j in range(n):
            if flow_on_edge.get((i, j), 0) > 0:
                adj_matrix[i][j] = flow_on_edge[(i, j)]
            # Account for staying at home (self edge)
            if flow_on_edge.get((i, i), 0) > 0:
                adj_matrix[i][i] += flow_on_edge[(i, i)]

    # Verify matrix satisfies constraints
    # Row sum should equal a[i] (all soldiers from city i are accounted for)
    # Column sum should equal b[i] (all soldiers arriving at city i)

    for i in range(n):
        row_sum = sum(adj_matrix[i][j] for j in range(n))
        if row_sum != a[i]:
            return "NO"

    for j in range(n):
        col_sum = sum(adj_matrix[i][j] for i in range(n))
        if col_sum != b[j]:
            return "NO"

    # Format output
    lines_out = ["YES"]
    for row in adj_matrix:
        lines_out.append(' '.join(map(str, row)))

    return '\n'.join(lines_out)

