import math

def get_divisors(n):
    """Return all divisors of n greater than 1."""
    divs = set()
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted([d for d in divs if d > 1])

def gcd(a, b):
    """Compute the greatest common divisor of a and b."""
    while b:
        a, b = b, a % b
    return a

def solve_test_case(n):
    """Solve a single test case and return formatted result."""
    divs = get_divisors(n)

    # Special case: exactly 2 divisors
    if len(divs) == 2:
        d1, d2 = divs
        if gcd(d1, d2) == 1:
            return f"{min(d1, d2)} {max(d1, d2)}\n1"
        else:
            return f"{min(d1, d2)} {max(d1, d2)}\n0"

    # Build arrangement starting with n (maximal divisor)
    # n shares a factor > 1 with every other divisor
    arrangement = [n]
    unused = set(d for d in divs if d != n)
    current = n

    # Greedy placement: pick divisor with highest gcd with current
    while unused:
        best = None
        best_shared = -1
        for cand in unused:
            shared = gcd(current, cand)
            if shared > best_shared:
                best_shared = shared
                best = cand

        if best_shared > 1:
            unused.remove(best)
            arrangement.append(best)
            current = best
        else:
            # No valid connection found, add remaining in sorted order
            for cand in sorted(unused):
                arrangement.append(cand)
            unused.clear()

    # Calculate number of coprime adjacent pairs (moves needed)
    moves = 0
    m = len(arrangement)
    for i in range(m):
        if gcd(arrangement[i], arrangement[(i + 1) % m]) == 1:
            moves += 1

    return ' '.join(map(str, arrangement)) + '\n' + str(moves)

