def f(x, k):
    while x > 0 and x % k == 0:
        x //= k
    return x

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    saved_operations = []
    success = [False]

    def get_operations(current_numbers, depth, operations, target_operations):
        nonlocal saved_operations, success
        if success[0]:
            return

        if len(current_numbers) == 1:
            if current_numbers[0] == 1:
                success[0] = True
                saved_operations = operations.copy()
            return

        for i in range(len(current_numbers) - 1):
            if success[0]:
                break
            for j in range(i + 1, len(current_numbers)):
                if success[0]:
                    break
                x = current_numbers[i]
                y = current_numbers[j]
                new_val = f(x + y, k)
                new_numbers = current_numbers[:i] + [new_val] + current_numbers[j+1:]
                operation = (x, y, new_val, i, j)
                operations.append(operation)
                get_operations(new_numbers, depth + 1, operations, target_operations)
                operations.pop()

    init_operations = []
    get_operations(a, 0, init_operations, init_operations)

    if not success[0]:
        return "NO"

    result_ops = []
    for op in saved_operations:
        x, y, new_val, i, j = op
        result_ops.append(f"{x} {y}")

    lines = ["YES"]
    lines.extend(result_ops)
    return "\n".join(lines)

