def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    t = int(lines[idx])
    idx += 1

    output_lines = []

    for case_num in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        ops = lines[idx]
        idx += 1

        for op in ops:
            if op == 'R':
                for i in range(n):
                    matrix[i] = [matrix[i][(j - 1) % n] for j in range(n)]
            elif op == 'L':
                for i in range(n):
                    matrix[i] = [matrix[i][(j + 1) % n] for j in range(n)]
            elif op == 'D':
                new_matrix = [[matrix[(i - 1) % n][j] for j in range(n)] for i in range(n)]
                matrix = new_matrix
            elif op == 'U':
                new_matrix = [[matrix[(i + 1) % n][j] for j in range(n)] for i in range(n)]
                matrix = new_matrix
            elif op == 'I':
                new_matrix = []
                for i in range(n):
                    row = matrix[i]
                    inv = [0] * n
                    for pos, val in enumerate(row):
                        inv[val - 1] = pos + 1
                    new_matrix.append(inv)
                matrix = new_matrix
            elif op == 'C':
                transposed = [[matrix[j][i] for j in range(n)] for i in range(n)]
                new_matrix = []
                for i in range(n):
                    col = transposed[i]
                    inv = [0] * n
                    for pos, val in enumerate(col):
                        inv[val - 1] = pos + 1
                    new_matrix.append(inv)
                matrix = new_matrix

        for row in matrix:
            output_lines.append(' '.join(map(str, row)))

        if case_num < t - 1:
            output_lines.append('')

    return '\n'.join(output_lines)

def solution(input_data):
    # Parse input
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    strings = [lines[i] for i in range(1, n + 1)]

    # Step 1: Filter out strings that are substrings of other strings
    # Sort by length to detect substrings correctly
    strings.sort(key=len)
    filtered = []
    for i, s in enumerate(strings):
        is_substring = False
        for j in range(i + 1, len(strings)):
            if strings[j] in s:
                is_substring = True
                break
        if not is_substring:
            filtered.append(s)

    # If no strings after filtering, return empty string (edge case)
    if not filtered:
        return "\n"

    # Step 2: Check if each string has unique characters
    for s in filtered:
        if len(set(s)) != len(s):
            return "NO\n"

    # Step 3: Check if any character appears in multiple filtered strings
    all_chars = set()
    for s in filtered:
        for c in s:
            if c in all_chars:
                return "NO\n"
            all_chars.add(c)

    # Step 4: Build graph and check for consistent structure
    graph = {}  # Each char -> its next char (0 or 1 outgoing)
    # Check for cycles and consistency
    elements = set()
    for s in filtered:
        for i in range(len(s) - 1):
            u, v = s[i], s[i + 1]
            uOut, uIn = elements.pop() if len(elements) > 0 else None, None

    # Rebuild graph properly
    edges_in = defaultdict(set)  # u -> set of strings that define u->v
    edges_out = defaultdict(set)  # filename

    incident_count = defaultdict(int)
    out_edges = defaultdict(set)
    in_edges = defaultdict(set)

    for s in filtered:
        for i in range(len(s) - 1):
            u, v = s[i], s[i+1]
            if v in out_edges[u]:
                continue
            out_edges[u].add(v)
            if v not in in_edges:
                in_edges[v] = set()
            in_edges[v].add(u)

    # Validate graph (at most one outgoing and one incoming edge per node)
    for c in edges_out:
        if len(out_edges[c]) != 1:
            return "NO\n"
    for c in in_edges:
        if len(in_edges[c]) > 1:
            return "NO\n"

    # Check for cycles
    visited = set()
    for start in keys in all_chars:
        if start not in visited:
            current = start
            path = [start]
            while current in out_edges:
                if current in visited:
                    return "NO\n"  # Cycle detected
                visited.add(current)
                current = out_edges[current]

    # Build connected components
    components = []
    for c in all_chars:
        component = [c]
        if c in out_edges:
            neighbor = out_edges[c]
            component.append(neighbor)
            path = ','.join(component)
            components.append(path)

    components.sort()
    result = ''.join(components)

    return result + '\n'

def solution(input_str):
    data = input_str.strip().split('\n')
    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        p = list(map(int, data[idx].split()))
        idx += 1

        directions = [''] * n
        covered = [False] * n

        possible = True

        for i in range(n):
            if covered[i]:
                continue

            found = False

            # Check if left neighbor can illuminate current
            if i > 0:
                left_p = p[i-1]

                # If left neighbor hasn't been assigned direction yet
                if not directions[i-1]:
                    if left_p > 0 and i <= (i-1) + left_p:
                        directions[i-1] = 'R'
                        covered[i-1] = True
                        covered[i] = True
                        found = True

                # If left neighbor already directed right
                elif directions[i-1] == 'R' and left_p > 0 and i <= (i-1) + left_p:
                    covered[i] = True
                    found = True

            if not found:
            # If right neighbor hasn't been assigned direction yet
                right_p = 0
                if i < n - 1:
                    if not directions[i+1]:
                        if p[i+1] > 0 and i >= (i+1) - p[i+1]:
                            directions[i+1] = 'L'
                            covered[i+1] = True
                            covered[i] = True
                            found = True
                        right_p = p[i+1]
                    elif directions[i+1] == 'L' and right_p > 0 and i >= (i+1) - right_p:
                        covered[i] = True
                        found = True

                if not found:
                    possible = False
                    break

        if possible:
            if all(covered):
                results.append("YES")
                results.append("".join(directions))
            else:
                results.append("NO")
        else:
            results.append("NO")
            for _ in range(n - idx):
                directions.append('')

        # Mark remaining as not covered
        for i in range(n):
            covered[i] = False

        results.append("NO")
        break
        idx += 1

    return '\n'.join(results)

