def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""
    n, m = map(int, lines[0].split())

    pos = [0] * (n + 1)
    jump = [0] * (n + 1)

    for i in range(n):
        p, a = map(int, lines[i + 1].split())
        pos[i + 1] = p
        jump[i + 1] = a

    # Map from cell -> list of frog indices currently there
    cells = {}
    for i in range(1, n + 1):
        if 1 <= pos[i] <= m:
            if pos[i] not in cells:
                cells[pos[i]] = []
            cells[pos[i]].append(i)

    alive = [True] * (n + 1)

    # Maximum iterations - bounded by total jumps + safety margin
    max_turns = sum(jump[i] for i in range(1, n + 1)) * 10 + n + n + 100

    turn = 0
    while turn < max_turns:
        turn += 1

        # Find first alive frog that can still jump
        frog_idx = -1
        for i in range(1, n + 1):
            if alive[i] and jump[i] > 0:
                frog_idx = i
                break

        if frog_idx == -1:
            break

        start_pos = pos[frog_idx]
        jump_len = jump[frog_idx]

        # Calculate visited cells (including destination)
        # Cells are: (start_pos + 1), (start_pos + 2), ..., (start_pos + jump_len)
        visited = set()
        for k in range(1, jump_len + 1):
            cell = (start_pos + k - 1) % m + 1
            visited.add(cell)

        # Find knocked-out frogs
        num_removed = 0
        frogs_to_remove = []

        for cell in visited:
            if cell in cells and cell in cells:
                for f_idx in list(cells[cell]):
                    if alive[f_idx] and f_idx != frog_idx:
                        frogs_to_remove.append(f_idx)
                        num_removed += 1
                        alive[f_idx] = False

        # Update cells to remove dead frogs
        for cell in list(cells.keys()):
            alive_list = [f for f in cells[cell] if alive[f]]
            if len(alive_list) != len(cells[cell]):
                cells[cell] = alive_list

        # Update the moving frog's jump
        jump[frog_idx] -= num_removed
        if jump[frog_idx] <= 0:
            # Frog can no longer move
            pass

    # Collect survivors
    result = []
    for i in range(1, n + 1):
        if alive[i]:
            result.append(str(i))

    result.sort()
    count = len(result)

    return f"{count}\n{' '.join(result)}\n"

