from collections import deque

def solution(input_str):
    """
    Find minimum operations to reduce n to 0 by subtracting digits present in n.
    """
    line = input_str.strip()
    if not line:
        return '0\n'

    n = int(line)
    if n == 0:
        return '0\n'

    visited = {n: 0}
    queue = deque([n])

    while queue:
        current = queue.popleft()
        current_ops = visited[current]

        if current == 0:
            return f"{current_ops}\n"

        digits = set()
        temp = current
        while temp > 0:
            digits.add(temp % 10)
            temp //= 10

        for d in sorted(digits, reverse=True):
            if d > 0:
                next_val = current - d
                if next_val not in visited:
                    visited[next_val] = current_ops + 1
                    queue.append(next_val)

    return '0\n'

