def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # 4 T-shapes defined as sets of (row, col) offsets from top-left
    shapes = [
        {(0,0), (0,1), (0,2), (1,1), (2,1)},  # Down T
        {(0,2), (1,0), (1,1), (1,2), (2,2)},  # Up T
        {(0,1), (1,0), (1,1), (1,2), (2,1)},  # Left T
        {(0,0), (1,0), (1,1), (1,2), (2,0)}   # Right T
    ]

    grid = [['.' for _ in range(m)] for _ in range(n)]

    best_count = [0]
    best_grid = [row[:] for row in grid]

    def can_place(r, c, shape):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m) or grid[nr][nc] != '.':
                return False
        return True

    def count_pieces():
        return sum(1 for row in grid for cell in row if cell != '.')

    def backtrack():
        current_count = count_pieces()

        # Update best if we have more pieces
        if current_count > best_count[0]:
            best_count[0] = current_count
            best_grid = [row[:] for row in grid]

        # Calculate remaining cells and estimate potential
        remaining_cells = n * m - current_count

        # If we can't possibly beat best count, prune this branch
        if best_count[0] + remaining_cells // 5 <= current_count and remaining_cells >= 0:
            return

        # Try to place more shapes
        for r in range(n):
            for c in range(m):
                if grid[r][c] != '.':
                    continue

                for idx, shape in enumerate(shapes):
                    # Try this shape at position (r, c)
                    if can_place(r, c, shape):
                        # Get next letter for this piece
                        letter = chr(ord('A') + count_pieces())

                        # Place the shape
                        for dr, dc in shape:
                            grid[r + dr][c + dc] = letter

                        # Recursively try to place more
                        backtrack()

                        # Backtrack (remove the shape)
                        for dr, dc in shape:
                            grid[r + dr][c + dc] = '.'

    # Start backtracking from empty grid
    backtrack()

    # Output result
    result = [str(best_count[0])]
    for row in best_grid:
        result.append(''.join(row))

    return '\n'.join(result) + '\n'

